import { imageHotspots } from './image-hotspots.ts';
import type { StudioPart } from './studio-parts.ts';

export type AssetPart = StudioPart & { node: string; offset: [number, number, number] };
export type StudioAsset = { src: string; reference: string; parts: AssetPart[] };

function fromImage(node: string, name: string, offset: AssetPart['offset'], id = 'anatomy-58'): AssetPart {
  const label = imageHotspots[id]?.find(part => part.name === name);
  if (!label) throw new Error(`Missing source label for ${node}`);
  return { node, offset, name: label.name, purpose: label.function, connection: label.connection };
}

function dedicatedAsset(id: string, parts: AssetPart[], directory = id.split('-')[0]): StudioAsset {
  return {
    src: `./models/hardware/${id}.glb`,
    reference: `./images/${directory}/${id}.webp`,
    parts,
  };
}

